const v=document.getElementById('viewer');if(v){const a={shoulders:'Front / side / rear deltoid',chest:'Upper chest · middle chest · lower chest',abs:'Upper abs · middle abs · lower abs',arms:'Biceps long head · short head · brachialis',back:'Upper back · middle back · lats · traps',glutes:'Glute max · glute medius',legs:'Quads · hamstrings · calves'};v.addEventListener('mousemove',e=>{const r=v.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;let k;if(v.classList.contains('back-view'))k=y<.28?'shoulders':y<.68?'back':y<.9?'glutes':'legs';else if(x<.25||x>.75)k='arms';else k=y<.3?'shoulders':y<.5?'chest':y<.8?'abs':'legs';const t=document.getElementById('muscle-tip');t.textContent=a[k];t.style.display='block';t.style.left=Math.min(e.clientX-r.left+12,r.width-205)+'px';t.style.top=Math.max(12,e.clientY-r.top-35)+'px'})}
